    stack = []
    asterisk = []
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == '*':
            asterisk.append(i)
        else: #closing parenthesis
            if not stack and not asterisk:
                return False
            elif stack:
                stack.pop()
